import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
  ZoomIn,
  ZoomOut,
  RotateCw,
  RefreshCw,
  Eye,
  Info,
  Maximize2,
} from 'lucide-react';

interface SampleHint {
  title: string;
  category: string;
  orientation: string;
  desc: string;
}

interface ImageViewerControlsProps {
  previewUrl: string | null;
  filename: string | null;
  scanType?: string | null;
  orientation?: string | null;
  onQuickLoadSample?: (index: number) => void;
  samples?: SampleHint[];
}

const ImageViewerControls: React.FC<ImageViewerControlsProps> = ({
  previewUrl,
  filename,
  scanType,
  orientation,
  onQuickLoadSample,
  samples = [],
}) => {
  const [zoom, setZoom] = useState(1);
  const [rotation, setRotation] = useState(0);
  const [fitMode, setFitMode] = useState(true);
  const containerRef = useRef<HTMLDivElement>(null);

  // Reset when image changes
  useEffect(() => {
    setZoom(1);
    setRotation(0);
    setFitMode(true);
  }, [previewUrl]);

  const handleZoomIn = useCallback(() => {
    setFitMode(false);
    setZoom((z) => Math.min(parseFloat((z + 0.25).toFixed(2)), 4));
  }, []);

  const handleZoomOut = useCallback(() => {
    setFitMode(false);
    setZoom((z) => Math.max(parseFloat((z - 0.25).toFixed(2)), 0.25));
  }, []);

  const handleRotate = useCallback(() => {
    setRotation((r) => (r + 90) % 360);
  }, []);

  const handleFitView = useCallback(() => {
    setZoom(1);
    setRotation(0);
    setFitMode(true);
  }, []);

  const handleReset = useCallback(() => {
    setZoom(1);
    setRotation(0);
    setFitMode(true);
  }, []);

  // Keyboard shortcuts
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!previewUrl) return;
      if (e.key === '+' || e.key === '=') handleZoomIn();
      if (e.key === '-') handleZoomOut();
      if (e.key === 'r' || e.key === 'R') handleRotate();
      if (e.key === 'Escape') handleReset();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [previewUrl, handleZoomIn, handleZoomOut, handleRotate, handleReset]);

  /* ─── Empty state ─── */
  if (!previewUrl) {
    return (
      <div className="rounded-2xl bg-slate-900/40 border border-slate-800 overflow-hidden">
        <div className="p-6 flex flex-col items-center text-center gap-4">
          <div className="w-14 h-14 rounded-full bg-slate-800/80 border border-slate-700/60 flex items-center justify-center">
            <Eye className="w-7 h-7 text-slate-500 stroke-[1.5]" aria-hidden="true" />
          </div>
          <div>
            <p className="text-sm font-semibold text-slate-300">No scan selected</p>
            <p className="text-xs text-slate-400 mt-1 max-w-xs mx-auto">
              Click a demo scan from the left panel, or drag and drop a Brain MRI file below.
            </p>
          </div>

          {samples.length > 0 && onQuickLoadSample && (
            <div className="w-full grid grid-cols-1 sm:grid-cols-2 gap-2 text-left">
              {samples.map((s, idx) => (
                <button
                  key={s.category}
                  type="button"
                  onClick={() => onQuickLoadSample(idx)}
                  aria-label={`Load demo scan: ${s.title}`}
                  className="group p-3 rounded-xl bg-slate-900/80 hover:bg-slate-800 border border-slate-800 hover:border-teal-500/50 transition-all text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-teal-500"
                >
                  <div className="flex items-center justify-between mb-0.5">
                    <span className="text-xs font-bold text-slate-200 group-hover:text-teal-300 transition-colors">
                      {s.title}
                    </span>
                    <span className="text-[10px] font-mono px-1.5 py-0.5 rounded bg-teal-500/10 text-teal-400 border border-teal-500/20 shrink-0 ml-1">
                      {s.orientation}
                    </span>
                  </div>
                  <p className="text-[11px] text-slate-400 line-clamp-1">{s.desc}</p>
                  <span className="text-[10px] text-teal-400 font-medium mt-1 inline-block">
                    ⚡ Load &amp; preview
                  </span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    );
  }

  /* ─── Active viewer ─── */
  const transformStyle: React.CSSProperties = {
    transform: `scale(${fitMode ? 1 : zoom}) rotate(${rotation}deg)`,
    transition: 'transform 0.2s ease-out',
    maxWidth: '100%',
    maxHeight: '100%',
  };

  return (
    <div className="space-y-2">
      {/* Toolbar */}
      <div
        className="flex flex-wrap items-center justify-between gap-2 px-3 py-2 rounded-xl bg-slate-900/80 border border-slate-800 text-xs"
        role="toolbar"
        aria-label="Image viewer controls"
      >
        {/* Filename + scan info */}
        <div className="flex items-center gap-2 min-w-0 flex-1">
          <span className="font-mono text-[11px] text-teal-400 truncate max-w-[160px]" title={filename || ''}>
            {filename || 'mri_scan.jpg'}
          </span>
          {(scanType || orientation) && (
            <span className="hidden sm:inline text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400 font-mono shrink-0">
              {[orientation, scanType].filter(Boolean).join(' · ')}
            </span>
          )}
        </div>

        {/* Control buttons */}
        <div className="flex items-center gap-1 shrink-0">
          {[
            { icon: ZoomIn, fn: handleZoomIn, label: 'Zoom in (+)', title: 'Zoom In (+)' },
            { icon: ZoomOut, fn: handleZoomOut, label: 'Zoom out (-)', title: 'Zoom Out (-)' },
            { icon: RotateCw, fn: handleRotate, label: 'Rotate 90°', title: 'Rotate 90° (R)' },
            { icon: Maximize2, fn: handleFitView, label: 'Fit to view', title: 'Fit to View' },
            { icon: RefreshCw, fn: handleReset, label: 'Reset view', title: 'Reset View (Esc)' },
          ].map(({ icon: Icon, fn, label, title }) => (
            <button
              key={label}
              type="button"
              onClick={fn}
              aria-label={label}
              title={title}
              className="p-1.5 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 hover:text-white transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-teal-500"
            >
              <Icon className="w-3.5 h-3.5" aria-hidden="true" />
            </button>
          ))}

          {/* Zoom / rotation readout */}
          <span className="ml-1 px-2 py-1 rounded-lg bg-slate-950 text-[10px] font-mono text-slate-400 select-none">
            {Math.round((fitMode ? 1 : zoom) * 100)}% &nbsp;
            {rotation}°
          </span>
        </div>
      </div>

      {/* Viewport */}
      <div
        ref={containerRef}
        className="relative h-72 sm:h-[22rem] md:h-[26rem] rounded-2xl bg-slate-950 border border-slate-800 overflow-hidden flex items-center justify-center"
        aria-label="MRI scan viewer"
      >
        <div
          className="flex items-center justify-center p-4 w-full h-full"
          style={{ overflow: 'hidden' }}
        >
          <img
            src={previewUrl}
            alt={`MRI scan preview — ${filename || 'selected scan'}`}
            style={transformStyle}
            className="object-contain rounded-lg shadow-2xl"
            draggable={false}
          />
        </div>

        {/* Zoom overlay hint */}
        {!fitMode && (
          <div className="absolute bottom-3 right-3 px-2 py-1 rounded-lg bg-slate-900/80 border border-slate-700 text-[10px] font-mono text-slate-400">
            {Math.round(zoom * 100)}%
          </div>
        )}
      </div>

      {/* Note */}
      <div className="flex items-start gap-1.5 text-[11px] text-slate-500">
        <Info className="w-3.5 h-3.5 shrink-0 mt-0.5" aria-hidden="true" />
        <span>
          Viewer adjustments (zoom, rotation) are applied client-side only and do not affect the image sent to the model.
          Keyboard: <kbd className="font-mono bg-slate-800 px-1 rounded">+</kbd>{' '}
          <kbd className="font-mono bg-slate-800 px-1 rounded">-</kbd>{' '}
          <kbd className="font-mono bg-slate-800 px-1 rounded">R</kbd>{' '}
          <kbd className="font-mono bg-slate-800 px-1 rounded">Esc</kbd>
        </span>
      </div>
    </div>
  );
};

export default ImageViewerControls;
